const resultElement=document.getElementById('results');
const statusElement=document.getElementById('generation-status');
let selectedCount=1;
function randomBelow(max){const value=new Uint32Array(1);const limit=Math.floor(4294967296/max)*max;do{crypto.getRandomValues(value)}while(value[0]>=limit);return value[0]%max}
function drawGame(){const pool=Array.from({length:45},(_,i)=>i+1);for(let i=0;i<6;i++){const j=i+randomBelow(45-i);[pool[i],pool[j]]=[pool[j],pool[i]]}return pool.slice(0,6).sort((a,b)=>a-b)}
function selectCount(count){selectedCount=count;document.querySelectorAll('[data-count]').forEach(button=>button.setAttribute('aria-pressed',String(Number(button.dataset.count)===count)))}
function generate(count=selectedCount){if(![1,3,5].includes(count))throw new Error('게임 수는 1, 3, 5 중 하나여야 합니다.');selectCount(count);const games=Array.from({length:count},drawGame);resultElement.replaceChildren();games.forEach((numbers,index)=>{const row=document.createElement('div');row.className='ball-row';row.setAttribute('aria-label',`${index+1}게임: ${numbers.join(', ')}`);const label=document.createElement('span');label.className='game-label';label.textContent=String.fromCharCode(65+index);label.setAttribute('aria-hidden','true');row.append(label);numbers.forEach((number,i)=>{const ball=document.createElement('span');ball.className='ball '+(number<=10?'':number<=20?'blue':number<=30?'red':number<=40?'gray':'green');ball.textContent=number;ball.style.animationDelay=`${i*45}ms`;ball.setAttribute('aria-hidden','true');row.append(ball)});resultElement.append(row)});statusElement.textContent=`${count}게임 생성 완료`;document.querySelector('#generate span').textContent='다시 뽑기';return {games}}
document.querySelectorAll('[data-count]').forEach(button=>button.addEventListener('click',()=>selectCount(Number(button.dataset.count))));
document.getElementById('generate').addEventListener('click',()=>generate());
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'generate_lotto_numbers',title:'로또 번호 생성',description:'1, 3, 5게임의 로또 번호를 생성하고 화면에 표시합니다.',inputSchema:{type:'object',properties:{count:{type:'integer',enum:[1,3,5]}},required:['count'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).some(key=>key!=='count'))throw new Error('잘못된 입력입니다.');return generate(input.count)}})).catch(()=>{})}catch{}}
